import{_ as t,o as e,c as o,a5 as s}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-039","description":"","frontmatter":{"date":"2020-08-27T19:48:16","title":"写作课作业-039","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/039.md","filePath":"posts/homework/039.md"}'),a={name:"posts/homework/039.md"};function r(_,p,c,n,l,i){return e(),o("div",null,[...p[0]||(p[0]=[s("<blockquote><p>8.27写作作业:你怎么理解“为人民服务”，你如何运用这理念到学习、生活和工作中，至少使用一个类比和递进。</p></blockquote><p>昨天看到简七读财的一篇推文——《月入10万，他靠的是这个「平平无奇」的小生意》。</p><blockquote><p>案例的主人公叫刘云强，是个90后。</p><p>别看他年纪不大，已经是10年以上的「养牛」资深玩家了。</p><p>刘云强小时候，算是让父母挺头疼的孩子——<strong>贪玩、学习成绩也不好，初中毕业就辍学了。</strong></p><p>在周围人的眼中，刘云强的「养牛」爱好，也特别不务正业，比如喜欢牛仔裤、有一帮「复古圈」的朋友，买各式各样的牛仔裤也花了不少钱。</p><p>可就是这些看起来「不务正业」的爱好，现在给他带来了每年超百万的收入。</p><p>2013年，在一次复古爱好者的聚会上，大家聊着聊着就说到，这个复古行业里，还没有一个专门去针对复古衣服修补的项目。</p><p>说者无意，听者有心。刘云强脑子就就蹦出一个念头，他想专门去做复古衣服（尤其是牛仔裤）的修补。</p><p>*“牛仔裤磨损最多的地方就是裆部，这是因为个人的生活习惯...”*被采访的刘云强，娓娓道来自己的最初的想法。</p><p>他大概统计了下，自己一年大概要补2000多个裤裆，收入大概有百万。</p></blockquote><p>我想这就是为人民服务——提供的服务能解决一部分人实际的问题。人民不是所有人，而是特定的群体，否则也服务不过来。服务呢，是奔着解决问题去的，从而产生价值。</p><p>然后服务是一种感同身受，我之前是做医疗软件的。刚开始强调服务意识的时候，大家也不太懂。后来这么说——不要让医生因为我们的软件不好用，产生踢猫效应，那个病人可能是你的家人；下次自己的家人去就诊时能感到方便，而不是骂娘。我们多少明白了些。</p><p>同时服务是一种责任，领导带团队就是要服务好团队。帮助团队成员发掘他们自身的潜质，帮助他们成长。</p>",6)])])}const k=t(a,[["render",r]]);export{m as __pageData,k as default};
